export function createRound(e){return{phase:"ready",elapsed:0,settled:0,seconds:e.seconds,spotless:!1}}export function resetRound(e){return e.phase="ready",e.elapsed=0,e.settled=0,e.spotless=!1,e}export function freePlay(e){return e.phase="free",e.elapsed=0,e.settled=0,e.spotless=!1,e}export function isOver(e){return e.phase==="finale"||e.phase==="done"}export function canBlow(e){return e.phase==="ready"||e.phase==="playing"||e.phase==="free"}export function timeLeft(e){return Math.max(0,e.seconds-e.elapsed)}export function stepRound(e,a,s,t){const l=a>0?a:0;return e.phase==="ready"?s.blowing?(e.phase="playing","start"):null:e.phase==="playing"?(e.elapsed+=l,s.spotless&&e.elapsed<e.seconds?(e.spotless=!0,e.settled=0,e.phase=t.finale?"finale":"done",e.phase):e.elapsed>=e.seconds?(e.elapsed=e.seconds,e.settled=0,e.phase=t.finale?"finale":"done",e.phase):null):e.phase==="finale"&&(e.settled+=l,s.finaleDone||e.settled>=t.finaleMax)?(e.phase="done","done"):null}
